export const MANAGING_EMOTIONS_ACTIVITIES = [
// FASE A — FONDASI / KONKRET (1-20): menenangkan diri & mengelola emosi
{n:1,type:"mcq",micro:"Apa itu mengelola emosi",q:"'Mengelola emosi' (regulasi emosi) berarti...",options:["Menyadari perasaan yang muncul & memilih cara merespons yang sehat, bukan sekadar menahan atau meledakkannya","Berusaha tidak pernah merasakan emosi apa pun","Selalu bertindak persis sesuai dorongan emosi saat itu"],answer:0,explain:"Mengelola bukan menghilangkan emosi, tapi mengambil ruang untuk memilih respons yang tidak disesali.",hint:"Menyadari & memilih respons sehat, atau menahan total / meledakkan?"},
{n:2,type:"mcq",micro:"Menekan vs mengelola",q:"Beda 'menekan emosi' dengan 'mengelola emosi':",options:["Menekan selalu lebih baik daripada mengelola","Menekan = berpura-pura tidak merasakan & mendorongnya jauh-jauh; mengelola = mengakui perasaan lalu menanganinya dengan cara yang sehat","Keduanya sama saja"],answer:1,explain:"Menekan sering membuat emosi menumpuk & muncul lagi dengan cara lain. Mengelola mengakui perasaan sambil tetap tenang dalam bertindak.",hint:"Menekan = berpura-pura, mengelola = mengakui & menangani, atau sama saja?"},
{n:3,type:"mcq",micro:"Menenangkan tubuh dulu",q:"Saat emosi sangat kuat, sering lebih efektif menenangkan tubuh dulu (napas, gerak) sebelum mencoba berpikir jernih karena...",options:["Tubuh tidak ada hubungannya dengan emosi","Berpikir jernih selalu mudah kapan pun","Saat tubuh dalam kondisi 'siaga tinggi', bagian otak yang berpikir tenang jadi sulit bekerja; menenangkan tubuh membuka jalan bagi pikiran jernih"],answer:2,explain:"Emosi kuat memicu respons tubuh (jantung berdebar, napas cepat). Menenangkan tubuh dulu sering lebih membantu daripada langsung 'memaksa diri berpikir positif'.",hint:"Tenangkan tubuh dulu supaya pikiran bisa jernih, atau langsung paksa berpikir?"},
{n:4,type:"mcq",micro:"Napas perlahan",q:"Menarik napas perlahan & menghembuskannya lebih lama dari menariknya bisa membantu karena...",options:["Napas yang lambat memberi sinyal pada tubuh bahwa keadaan aman, membantu menurunkan rasa 'siaga'","Napas tidak memengaruhi perasaan sama sekali","Menahan napas lebih efektif"],answer:0,explain:"Napas adalah salah satu hal yang bisa kita kendalikan secara sadar untuk menenangkan sistem tubuh saat emosi memuncak.",hint:"Napas lambat memberi sinyal aman, atau tak berpengaruh / tahan napas lebih baik?"},
{n:5,type:"mcq",micro:"Teknik 5-4-3-2-1",q:"Teknik 'grounding' 5-4-3-2-1 (menyebutkan 5 hal yang dilihat, 4 yang didengar, 3 yang bisa disentuh, 2 yang dicium, 1 yang dirasakan) membantu ketika...",options:["Ingin tidur","Merasa sangat cemas atau kewalahan, membantu perhatian kembali ke saat ini & tempat sekarang","Sedang merasa bosan"],answer:1,explain:"Grounding mengalihkan perhatian dari pikiran yang berputar cepat ke pengamatan konkret di sekitar kita, membantu 'kembali membumi'.",hint:"Membantu saat cemas/kewalahan, atau saat bosan?"},
{n:6,type:"mcq",micro:"Ambil jeda",q:"Kalau kamu merasa akan bereaksi dengan cara yang mungkin disesali (membentak, membanting), langkah yang bijak:",options:["Lanjutkan bereaksi karena 'sudah terlanjur emosi'","Menahan sambil tetap di situasi & meledak sedikit lagi nanti","Ambil jeda, tinggalkan situasi sebentar bila bisa ('aku mau ke luar sebentar'), tenangkan diri, baru kembali"],answer:2,explain:"Jeda memberi waktu bagi emosi memuncak untuk mulai mereda, sehingga respons berikutnya bisa lebih dipilih.",hint:"Ambil jeda & tenangkan diri, atau lanjut bereaksi / menahan lalu meledak?"},
{n:7,type:"mcq",micro:"Ruang jeda pribadi",q:"Memiliki 'tempat aman' atau kegiatan yang bisa dipakai untuk menenangkan diri (sudut kamar, jalan kaki, mendengarkan musik) berguna karena...",options:["Kamu tahu apa yang bisa dilakukan saat perlu menenangkan diri, tanpa harus memikirkannya dari nol saat sedang kewalahan","Tidak ada gunanya menyiapkan hal seperti itu","Menenangkan diri hanya bisa dilakukan dengan bantuan orang lain"],answer:0,explain:"Menyiapkan 'rencana menenangkan diri' saat sedang tenang membuat lebih mudah menerapkannya saat sedang kesulitan.",hint:"Sudah siap saat dibutuhkan, atau tak berguna / harus selalu dibantu orang?"},
{n:8,type:"mcq",micro:"Emosi sebagai gelombang",q:"Mengingat bahwa emosi kuat biasanya 'memuncak lalu mereda' membantu saat kewalahan karena...",options:["Emosi tidak pernah berubah","Kita jadi tahu bahwa perasaan yang sangat berat ini kemungkinan besar akan berkurang, kita hanya perlu bertahan melewati puncaknya","Berarti kita tidak perlu melakukan apa pun karena semua pasti hilang sendiri"],answer:1,explain:"'Ini akan berlalu' bukan berarti mengabaikan perasaan, tapi mengingat bahwa intensitas puncak tidak bertahan selamanya.",hint:"Membantu bertahan melewati puncak, atau berarti tak perlu apa-apa / emosi tak berubah?"},
{n:9,type:"order",micro:"Langkah menenangkan diri saat emosi memuncak",q:"Urutkan langkah menenangkan diri saat merasakan emosi yang sangat kuat.",items:["Sadari: 'aku sedang sangat [marah/cemas/sedih], tubuhku bereaksi'","Beri jeda: kalau bisa, jauhkan diri sebentar dari pemicunya","Tenangkan tubuh: napas perlahan beberapa kali, atau grounding 5-4-3-2-1","Setelah lebih tenang, pikirkan apa langkah selanjutnya yang paling baik"],answer:[0,1,2,3],explain:"Sadari → jeda → tenangkan tubuh → baru pikirkan langkah. Berpikir jernih datang setelah tubuh sedikit tenang, bukan sebaliknya.",hint:"Memikirkan langkah selanjutnya dilakukan sebelum atau sesudah menenangkan tubuh?"},
{n:10,type:"mcq",micro:"Mengelola bukan berarti selalu tenang",q:"Orang yang pandai mengelola emosi...",options:["Tidak pernah lagi merasakan emosi kuat sama sekali","Selalu terlihat tenang dengan menahan semuanya","Tetap merasakan emosi kuat kadang-kadang, tapi lebih mampu menenangkan diri & memilih respons yang baik"],answer:2,explain:"Tujuannya bukan 'tidak pernah kesal', tapi bisa pulih & memilih tindakan yang tidak merugikan diri atau orang lain.",hint:"Tetap merasakan emosi tapi bisa pulih & memilih respons, atau tak pernah emosi / menahan semua?"},
{n:11,type:"tf",micro:"Menenangkan diri bisa dilatih",q:"Benar atau Salah: Teknik menenangkan diri (napas, grounding, jeda) bisa dilatih & jadi lebih mudah dipakai dengan latihan berulang, terutama bila dipraktikkan juga saat tidak sedang emosi.",answer:true,explain:"Melatih teknik ini saat tenang membuatnya lebih otomatis & bisa diandalkan saat benar-benar dibutuhkan.",hint:"Bisa dilatih & jadi lebih mudah, atau hanya berhasil bila 'berbakat tenang'?"},
{n:12,type:"tf",micro:"Meledak melegakan?",q:"Benar atau Salah: Melampiaskan kemarahan dengan meledak (membentak, membanting) selalu membuat kita merasa lega & menyelesaikan masalah.",answer:false,explain:"Sebaliknya, meledak sering menambah masalah (menyakiti orang, merusak barang, penyesalan) & kadang justru membuat kemarahan bertahan lebih lama, bukan mereda.",hint:"Selalu melegakan & menyelesaikan, atau sering menambah masalah?"},
{n:13,type:"mcq",micro:"Menunda reaksi penting",q:"Untuk hal penting (membalas pesan yang membuat marah, membuat keputusan), 'aturan 24 jam' atau setidaknya beberapa jam berguna karena...",options:["Memberi waktu emosi untuk mereda sehingga respons yang dibuat lebih bijak & jarang disesali","Membuat kita jadi pengecut yang menghindar","Tidak berpengaruh pada kualitas keputusan"],answer:0,explain:"Menunda reaksi bukan menghindar, tapi memberi ruang agar keputusan tidak dibuat di puncak emosi.",hint:"Memberi waktu untuk respons lebih bijak, atau membuat pengecut / tak berpengaruh?"},
{n:14,type:"mcq",micro:"Gerak tubuh & emosi",q:"Aktivitas fisik (berjalan, berlari, melompat, meregangkan badan) bisa membantu mengelola emosi karena...",options:["Membuat emosi jadi lebih buruk","Membantu 'membakar' energi berlebih dari emosi kuat (terutama marah & cemas) & sering memperbaiki suasana hati","Tidak ada hubungan antara gerak & emosi"],answer:1,explain:"Emosi kuat sering datang dengan energi fisik. Menggerakkan tubuh memberi jalan keluar yang sehat untuk energi itu.",hint:"Membakar energi & perbaiki suasana hati, atau tak berhubungan / memperburuk?"},
{n:15,type:"mcq",micro:"Bicara ke diri sendiri (self-talk)",q:"Cara berbicara ke diri sendiri saat emosi ('aku pasti gagal, aku memang payah' vs 'ini sulit, tapi aku bisa coba langkah demi langkah') memengaruhi...",options:["Tidak ada apa-apa, self-talk tidak berpengaruh","Hanya membuat kita jadi berbohong pada diri sendiri","Seberapa besar emosi itu terasa & seberapa mampu kita menghadapinya"],answer:2,explain:"Kata-kata yang kita ucapkan dalam hati bisa memperbesar atau menenangkan emosi. Self-talk yang lebih adil & mendukung membantu.",hint:"Memengaruhi besar emosi & kemampuan menghadapi, atau tak berpengaruh?"},
{n:16,type:"tf",micro:"Menenangkan diri bukan menghindar",q:"Benar atau Salah: Menenangkan diri sebelum menghadapi masalah sama saja dengan menghindari masalah itu selamanya.",answer:false,explain:"Sebaliknya, keduanya berbeda: jeda untuk menenangkan diri lalu kembali menghadapi masalah adalah sehat & membantu menghadapinya lebih baik; terus-menerus menghindar tanpa pernah menghadapi membiarkan masalah menumpuk.",hint:"Berbeda, atau sama-sama menghindar?"},
{n:17,type:"mcq",micro:"Menulis untuk melepaskan",q:"Menulis bebas tentang apa yang dirasakan (tanpa peduli rapi atau tidak) saat emosi kuat bisa membantu karena...",options:["'Mengeluarkan' isi kepala ke kertas sering mengurangi tekanan & membuat perasaan lebih jelas","Membuat perasaan jadi lebih kuat & menetap","Tidak berguna kecuali tulisannya bagus"],answer:0,explain:"Menulis adalah cara aman melepaskan & memproses emosi, terutama yang sulit dibicarakan langsung ke orang.",hint:"Mengurangi tekanan & memperjelas, atau memperkuat perasaan / harus bagus?"},
{n:18,type:"mcq",micro:"Mendengarkan tubuh: butuh apa",q:"Setelah menenangkan diri, bertanya 'apa yang aku butuhkan sekarang?' bisa mengarah pada jawaban seperti...",options:["Selalu 'lebih banyak bekerja tanpa henti'","Istirahat, makan, bicara dengan seseorang, menyelesaikan masalah yang memicunya, atau sekadar melakukan hal yang menyenangkan sebentar","Tidak ada jawaban yang berguna"],answer:1,explain:"Emosi sering menandakan kebutuhan yang belum terpenuhi. Menenangkan diri lalu memenuhi kebutuhan itu adalah pengelolaan yang utuh.",hint:"Bisa mengarah ke kebutuhan nyata, atau tak ada jawaban / selalu 'bekerja lebih'?"},
{n:19,type:"mcq",micro:"Menenangkan diri di depan orang lain",q:"Kalau kamu merasa emosi memuncak saat sedang bersama orang lain & perlu menenangkan diri, hal yang wajar dilakukan:",options:["Menahan mati-matian sampai meledak di depan mereka","Pergi tanpa sepatah kata pun & tidak pernah kembali membahasnya","Katakan dengan jujur 'aku butuh waktu sebentar untuk menenangkan diri, nanti kita lanjutkan' lalu ambil jeda"],answer:2,explain:"Mengomunikasikan kebutuhan untuk jeda dengan jujur adalah dewasa & sehat, bukan tanda kelemahan.",hint:"Komunikasikan butuh jeda & ambil, atau tahan sampai meledak / pergi tanpa kabar?"},
{n:20,type:"open",micro:"Buat 'kotak alat' menenangkan diri",q:"Buat daftar 'kotak alat' (toolbox) pribadimu untuk menenangkan diri. Sertakan minimal: (a) 2 teknik cepat (bisa dilakukan di mana saja dalam 1-2 menit), (b) 2 kegiatan yang butuh sedikit lebih banyak waktu/ruang, (c) 1 orang yang bisa kamu ajak bicara, (d) untuk masing-masing, jelaskan kapan alat itu paling cocok dipakai.",sample:"Kotak Alat Menenangkan Diriku: (a) Teknik cepat: (1) Napas kotak, tarik napas 4 hitungan, tahan 4, hembuskan 4, tahan 4, ulang 4 kali. Cocok saat aku mulai merasa panik atau jantung berdebar, misalnya sebelum presentasi atau saat tiba-tiba cemas di kelas. (2) Grounding 5-4-3-2-1, menyebutkan hal yang kulihat/dengar/sentuh di sekitarku. Cocok saat pikiranku berputar cepat & aku merasa 'melayang' atau kewalahan, membantu aku kembali ke saat ini. (b) Kegiatan yang butuh lebih banyak waktu: (1) Jalan kaki keliling blok sekitar 10-15 menit sambil mendengarkan musik. Cocok saat aku marah & butuh membakar energi, atau setelah pertengkaran, supaya aku tidak membalas dalam keadaan panas. (2) Menulis bebas di buku catatan selama 10 menit tentang apa pun yang kurasakan. Cocok saat aku merasa sedih atau bingung & belum siap bercerita ke orang, menulis membantu aku memahami apa yang sebenarnya kurasakan. (c) Orang yang bisa kuajak bicara: kakakku. Cocok saat aku sudah agak tenang tapi masih butuh didengar atau butuh pendapat, dia biasanya mendengarkan tanpa langsung menghakimi. (d) Prinsip umum: teknik cepat untuk 'pertolongan pertama' saat emosi memuncak; kegiatan lebih panjang untuk memproses setelah puncaknya lewat; bicara ke orang saat aku butuh perspektif atau dukungan, bukan saat masih sangat panas karena aku bisa mengucapkan hal yang kusesali.",explain:"Jawaban baik: minimal 2 teknik cepat yang benar-benar bisa dilakukan di mana saja, 2 kegiatan yang butuh sedikit ruang/waktu, 1 orang spesifik, & penjelasan kapan masing-masing paling cocok (menunjukkan pemahaman bahwa alat berbeda cocok untuk situasi berbeda, mis. teknik cepat saat puncak, kegiatan panjang untuk memproses setelahnya).",hint:"Untuk (d), pikirkan: alat mana untuk 'pertolongan pertama' saat emosi memuncak, & mana untuk 'memproses' setelah puncaknya lewat?"},

// FASE B — PEMAHAMAN (21-40): mengubah pikiran, memilih respons
{n:21,type:"classify",micro:"Cara sehat vs kurang sehat menghadapi emosi",q:"Kelompokkan tiap cara ke 'Sehat' atau 'Kurang sehat' dalam menghadapi emosi kuat.",items:["Ambil jeda & napas perlahan sebelum merespons","Melampiaskan kemarahan dengan membentak orang lain","Menulis atau berbicara dengan orang tepercaya","Menghindari semua hal yang memicu perasaan itu selamanya tanpa pernah menghadapinya"],groups:["Sehat","Kurang sehat"],answer:{"Sehat":["Ambil jeda & napas perlahan sebelum merespons","Menulis atau berbicara dengan orang tepercaya"],"Kurang sehat":["Melampiaskan kemarahan dengan membentak orang lain","Menghindari semua hal yang memicu perasaan itu selamanya tanpa pernah menghadapinya"]},explain:"Sehat: menenangkan diri, memproses lewat menulis/bicara. Kurang sehat: melampiaskan ke orang lain, menghindar total selamanya.",hint:"Menenangkan & memproses, atau melampiaskan ke orang lain / menghindar total?"},
{n:22,type:"mcq",micro:"Menilai ulang situasi (reappraisal)",q:"'Menilai ulang' sebuah situasi berarti...",options:["Mencoba melihat situasi dari sudut lain yang mungkin lebih akurat atau kurang mengancam (mis. 'dia tidak membalas pesanku' → 'mungkin dia sibuk' bukan 'dia marah padaku')","Berbohong pada diri sendiri bahwa masalah tidak ada","Selalu berpikir negatif untuk 'realistis'"],answer:0,explain:"Menilai ulang bukan menyangkal kenyataan, tapi memeriksa apakah tafsir pertama kita (yang sering paling menakutkan) benar-benar yang paling mungkin.",hint:"Melihat dari sudut yang mungkin lebih akurat, atau berbohong / selalu negatif?"},
{n:23,type:"mcq",micro:"Pikiran otomatis yang menakutkan",q:"Saat emosi kuat, pikiran otomatis yang muncul sering...",options:["Netral & seimbang","Berlebihan, ekstrem, atau berfokus pada kemungkinan terburuk ('semua orang membenciku', 'ini bencana total')","Selalu paling akurat & bijak"],answer:1,explain:"Emosi kuat menghasilkan pikiran yang 'diwarnai' emosi itu. Menyadari ini membantu kita tidak langsung percaya setiap pikiran yang muncul saat sedang kalut.",hint:"Sering berlebihan & ekstrem, atau selalu akurat / netral?"},
{n:24,type:"mcq",micro:"Bertanya pada pikiran",q:"Cara memeriksa sebuah pikiran yang membuat emosi memuncak:",options:["Selalu percaya pikiran pertama karena 'dari hati'","Mengabaikan semua pikiran sepenuhnya","'Apa bukti untuk & melawan pikiran ini? Apakah ada penjelasan lain? Apa yang akan kukatakan pada teman yang berpikir begini?'"],answer:2,explain:"Memeriksa pikiran dengan pertanyaan seperti ini membantu memisahkan 'yang terasa benar saat kalut' dari 'yang sebenarnya lebih mungkin'.",hint:"Periksa dengan pertanyaan, atau percaya pikiran pertama / abaikan semua?"},
{n:25,type:"mcq",micro:"Berbicara pada diri seperti pada teman",q:"Kenapa berguna bertanya 'apa yang akan kukatakan pada teman yang mengalami ini?' saat sedang menghadapi emosi sulit sendiri?",options:["Kita biasanya jauh lebih baik & lebih adil pada teman daripada pada diri sendiri; ini membantu memberi diri kebaikan yang sama","Tidak ada gunanya, diri sendiri berbeda dari teman","Kita harus selalu lebih keras pada diri sendiri"],answer:0,explain:"'Belas kasih pada diri sendiri' (self-compassion), memperlakukan diri seperti kita memperlakukan teman yang kita sayangi, adalah cara sehat menghadapi kesulitan.",hint:"Memberi diri kebaikan yang sama seperti pada teman, atau harus lebih keras pada diri?"},
{n:26,type:"mcq",micro:"Memilih respons, bukan reaksi otomatis",q:"Beda 'reaksi' (otomatis, langsung) dengan 'respons' (dipilih setelah jeda):",options:["Reaksi selalu lebih baik karena lebih cepat","Reaksi terjadi tanpa berpikir; respons melibatkan jeda untuk memilih tindakan yang sesuai dengan nilai & situasi","Keduanya sama saja"],answer:1,explain:"Antara emosi & tindakan ada ruang, meski kadang sangat kecil. Melatih diri memakai ruang itu adalah inti mengelola emosi.",hint:"Reaksi otomatis vs respons yang dipilih, atau sama saja?"},
{n:27,type:"tf",micro:"Menenangkan diri tidak selalu langsung berhasil",q:"Benar atau Salah: Kalau teknik menenangkan diri tidak langsung bekerja dalam beberapa detik pertama, itu berarti tekniknya tidak cocok & harus segera ditinggalkan.",answer:false,explain:"Sebaliknya, emosi yang sudah sangat memuncak butuh beberapa menit atau beberapa kali percobaan untuk mulai mereda meski kita melakukan hal yang benar. Kesabaran & konsistensi penting.",hint:"Butuh waktu & wajar, atau harus langsung berhasil atau berarti gagal?"},
{n:28,type:"tf",micro:"Menghindari coping tidak sehat",q:"Benar atau Salah: Semua cara 'menenangkan diri' sama sehatnya, selama memberi kelegaan sesaat.",answer:false,explain:"Sebaliknya, beberapa cara (selalu menghindari, melampiaskan ke orang lain, terus mengalihkan diri tanpa pernah menghadapi masalah) kurang sehat bila jadi kebiasaan utama, karena tidak menyelesaikan akar masalah & bisa menimbulkan masalah baru.",hint:"Bisa kurang sehat bila jadi kebiasaan utama, atau semua cara menenangkan diri sama sehatnya?"},
{n:29,type:"mcq",micro:"Menerima emosi sambil mengelola",q:"Mengelola emosi yang sehat menggabungkan...",options:["Hanya menerima perasaan tanpa pernah menenangkan diri","Hanya menenangkan diri tanpa pernah mengakui perasaan","Menerima bahwa perasaan itu ada & wajar, DENGAN menenangkan diri & memilih tindakan yang baik, bukan salah satunya saja"],answer:2,explain:"Menerima ('aku boleh merasa marah') & mengelola ('tapi aku tidak akan membalas dengan menyakiti') berjalan bersama, bukan bertentangan.",hint:"Menerima + menenangkan + memilih tindakan, atau hanya salah satu?"},
{n:30,type:"order",micro:"Menghadapi pikiran yang memperbesar emosi",q:"Urutkan langkah menghadapi pikiran yang membuat emosi terasa makin besar.",items:["Sadari pikiran yang sedang muncul ('aku berpikir semua orang membenciku')","Tenangkan tubuh sedikit dulu (napas) agar bisa berpikir lebih jernih","Periksa pikiran itu: apa buktinya? apa penjelasan lain yang mungkin?","Ganti dengan pikiran yang lebih adil & seimbang, meski tetap mengakui situasinya sulit"],answer:[0,1,2,3],explain:"Sadari pikiran → tenangkan tubuh → periksa → ganti dengan yang lebih adil. Menenangkan tubuh dulu membuat pemeriksaan pikiran lebih mungkin berhasil.",hint:"Memeriksa pikiran dilakukan sebelum atau sesudah menenangkan tubuh sedikit?"},
{n:31,type:"mcq",micro:"Emosi & keputusan menunggu",q:"Kalimat yang bisa kamu katakan pada diri sendiri saat ingin membuat keputusan besar di puncak emosi:",options:["'Aku akan pikirkan ini lagi besok setelah tenang; kalau memang keputusan yang tepat, ia akan tetap tepat besok'","'Aku harus putuskan sekarang juga selagi berani'","'Perasaan ini pasti akan bertahan selamanya jadi keputusannya harus sekarang'"],answer:0,explain:"Keputusan yang benar-benar tepat biasanya tetap terasa tepat setelah emosi mereda. Menunggu jarang merugikan, terburu-buru sering iya.",hint:"Pikirkan lagi setelah tenang, atau putuskan sekarang selagi 'berani'?"},
{n:32,type:"tf",micro:"Emosi tidak harus dituruti perintahnya",q:"Benar atau Salah: Kalau emosi datang dengan dorongan untuk bertindak (marah → ingin membalas, takut → ingin lari), kita wajib menuruti dorongan itu.",answer:false,explain:"Sebaliknya, kita bisa mengakui dorongan itu tanpa menurutinya. 'Aku ingin membentak dia' tidak berarti harus membentak, ada jarak antara dorongan & tindakan yang bisa diperlebar dengan latihan.",hint:"Bisa akui dorongan tanpa menuruti, atau harus selalu menuruti dorongan emosi?"},
{n:33,type:"mcq",micro:"Menyeimbangkan menahan & mengekspresikan",q:"Cara sehat mengekspresikan emosi yang kuat:",options:["Selalu meledak agar 'jujur' pada perasaan","Mengungkapkannya dengan kata-kata pada waktu & orang yang tepat ('aku merasa terluka soal itu'), bukan menahan total maupun meledak sembarangan","Selalu menahan semua emosi tanpa pernah mengungkapkannya"],answer:1,explain:"Ada jalan tengah: mengungkapkan perasaan dengan jelas & terkendali, di waktu & tempat yang sesuai.",hint:"Ungkapkan dengan kata-kata pada waktu tepat, atau tahan total / meledak?"},
{n:34,type:"mcq",micro:"Emosi & waktu pulih berbeda tiap orang",q:"Berapa lama seseorang butuh untuk 'pulih' dari emosi kuat...",options:["Selalu tepat 5 menit untuk semua orang","Kalau lebih dari sejam berarti orang itu bermasalah","Berbeda-beda tergantung orang, jenis emosi, & situasinya; tidak ada 'waktu yang benar' yang berlaku untuk semua"],answer:2,explain:"Menghormati bahwa waktu pulih berbeda-beda membantu kita tidak menghakimi diri sendiri ('kok aku masih kesal?') atau orang lain.",hint:"Berbeda tergantung konteks, atau selalu 5 menit / lebih dari sejam bermasalah?"},
{n:35,type:"mcq",micro:"Mengelola emosi sebelum & sesudah situasi sulit",q:"Untuk situasi yang kamu tahu akan memicu emosi (ujian, konfrontasi, presentasi), pengelolaan emosi bisa dilakukan...",options:["Sebelum (bersiap secara mental, latihan menenangkan diri), selama (teknik cepat saat terasa memuncak), & sesudah (memproses & merawat diri)","Hanya saat emosi sudah memuncak, tidak sebelum atau sesudah","Tidak bisa direncanakan sama sekali"],answer:0,explain:"Pengelolaan emosi yang matang mencakup persiapan, penanganan saat itu, & pemulihan setelahnya, bukan hanya bereaksi di tengah badai.",hint:"Sebelum, selama, & sesudah, atau hanya saat memuncak / tak bisa direncanakan?"},
{n:36,type:"mcq",micro:"Emosi kuat sebagai info, bukan perintah",q:"Rasa takut yang sangat kuat sebelum mencoba hal baru (yang sebenarnya aman) bisa disikapi dengan...",options:["Memaksa diri tanpa menenangkan diri sama sekali","Mengakui rasa takutnya, menenangkan diri, & tetap mencoba langkah demi langkah, karena takut tidak selalu berarti 'jangan lakukan'","Selalu membatalkan apa pun yang membuat takut"],answer:1,explain:"Takut kadang melindungi kita dari bahaya nyata, tapi kadang hanya reaksi terhadap ketidakpastian. Membedakannya (& menenangkan diri) membantu memilih dengan bijak.",hint:"Akui, tenangkan, & tetap coba bertahap, atau selalu batalkan / paksa tanpa menenangkan?"},
{n:37,type:"tf",micro:"Menenangkan diri di depan orang lain itu wajar",q:"Benar atau Salah: Meminta jeda di tengah percakapan yang memanas ('aku butuh waktu sebentar, nanti kita lanjutkan') selalu berarti menghindar & tidak dewasa.",answer:false,explain:"Sebaliknya, jeda yang jujur & diikuti kembali menghadapi percakapan adalah tanda kedewasaan, lebih baik daripada memaksakan diri sampai meledak atau mengucapkan hal yang disesali.",hint:"Tanda kedewasaan, atau menghindar?"},
{n:38,type:"mcq",micro:"Emosi & kebiasaan sehat",q:"Kebiasaan sehari-hari (tidur cukup, bergerak, makan teratur) memengaruhi kemampuan mengelola emosi karena...",options:["Tidak ada hubungan antara kebiasaan fisik & emosi","Kebiasaan sehat hanya penting untuk tubuh, bukan perasaan","Tubuh yang lelah, lapar, atau kurang tidur membuat emosi lebih mudah meledak & lebih sulit ditenangkan"],answer:2,explain:"Merawat kebutuhan dasar tubuh adalah 'fondasi' yang membuat pengelolaan emosi jauh lebih mungkin berhasil.",hint:"Tubuh lelah/lapar bikin emosi lebih sulit dikelola, atau tak berhubungan?"},
{n:39,type:"mcq",micro:"Menerima bahwa strategi tidak selalu cukup",q:"Kalau kamu sudah mencoba berbagai teknik menenangkan diri tapi emosi tetap terasa sangat berat & sulit dikelola dalam waktu lama, langkah yang bijak:",options:["Bicara dengan orang dewasa tepercaya atau mencari bantuan profesional; beberapa perasaan butuh dukungan lebih dari yang bisa kita tangani sendiri","Terus mencoba sendiri sampai berhasil, apa pun yang terjadi","Menyerah & menganggap kita memang tidak bisa dibantu"],answer:0,explain:"Mengenali batas 'yang bisa kutangani sendiri' & mencari bantuan adalah bagian dari mengelola emosi dengan bijak, bukan kegagalan.",hint:"Cari bantuan bila strategi tak cukup, atau terus sendiri / menyerah?"},
{n:40,type:"open",micro:"Menghadapi pikiran yang memperbesar emosi",q:"Pilih satu situasi yang sering memicu emosi kuat & pikiran yang menakutkan. Tulis: (a) situasinya & pikiran otomatis yang muncul, (b) emosi yang menyertai & intensitasnya (1-10), (c) periksa pikiran itu: bukti untuk & melawan, penjelasan lain yang mungkin, apa yang akan kamu katakan pada teman yang berpikir begini, (d) pikiran alternatif yang lebih adil & seimbang (tetap jujur pada kesulitannya), (e) apakah emosi terasa sedikit berbeda setelah proses ini.",sample:"(a) Situasi: aku mengangkat tangan di kelas & jawabanku salah. Pikiran otomatis: 'Semua orang pasti menganggapku bodoh sekarang & akan mengingatnya lama.' (b) Emosi: malu & cemas, intensitas sekitar 8 dari 10. (c) Memeriksa pikiran: Bukti untuk, beberapa orang mungkin memang memperhatikan. Bukti melawan, aku sendiri jarang mengingat lama saat teman lain menjawab salah, biasanya aku lupa dalam beberapa menit; guru bahkan bilang 'nggak apa-apa, hampir benar' & lanjut ke materi berikutnya; kelas terlalu sibuk memikirkan pelajaran untuk terus memikirkan satu jawaban salah. Penjelasan lain, mungkin sebagian besar orang tidak benar-benar memperhatikan atau sudah lupa. Apa yang kukatakan pada teman, 'Berani menjawab itu bagus, salah itu bagian dari belajar, besok juga sudah tidak ada yang ingat.' (d) Pikiran alternatif: 'Aku berani mencoba menjawab, itu hal yang baik. Jawabanku salah, itu tidak nyaman tapi wajar & tidak membuatku bodoh. Kemungkinan besar teman-teman sudah lupa dalam beberapa menit, sama seperti aku melupakan kesalahan mereka.' (e) Setelah proses ini, rasa malunya turun jadi sekitar 4 dari 10, masih ada sedikit tidak nyaman tapi jauh lebih bisa kutangani, & aku merasa lebih siap untuk mengangkat tangan lagi lain kali.",explain:"Jawaban baik: situasi & pikiran otomatis yang spesifik, emosi & intensitas yang jelas, pemeriksaan pikiran yang benar-benar mempertimbangkan bukti kedua sisi & penjelasan alternatif (bukan hanya 'harusnya berpikir positif'), pikiran alternatif yang lebih adil TAPI tetap jujur (tidak menyangkal bahwa itu tidak nyaman), & refleksi jujur tentang apakah emosi berubah.",hint:"Bagian (c) kuncinya, cari bukti MELAWAN pikiran menakutkan itu (mis. 'apakah aku sendiri mengingat lama saat orang lain salah?')."},

// FASE C — PENERAPAN (41-60): teknik & praktik
{n:41,type:"mcq",micro:"Napas kotak (box breathing)",q:"'Napas kotak' berarti bernapas dengan pola...",options:["Menahan napas selama mungkin","Tarik 4 hitungan, tahan 4, hembuskan 4, tahan 4, lalu ulang beberapa kali","Bernapas secepat mungkin"],answer:1,explain:"Pola yang teratur & lambat ini membantu menenangkan sistem tubuh. Bisa dilakukan diam-diam di mana saja.",hint:"Pola teratur 4-4-4-4, atau secepat mungkin / tahan lama?"},
{n:42,type:"mcq",micro:"Grounding lewat sentuhan",q:"Memegang benda dengan tekstur menarik (batu halus, kain, es batu), atau menekan kaki ke lantai sambil memperhatikan sensasinya, membantu karena...",options:["Tidak ada efeknya","Membuat kita jadi lebih cemas","Sensasi fisik yang kuat menarik perhatian kembali ke tubuh & saat ini, menjauh dari pikiran yang berputar"],answer:2,explain:"Grounding lewat sentuhan/sensasi adalah cara cepat 'kembali membumi' saat pikiran terasa kacau atau melayang.",hint:"Menarik perhatian ke tubuh & saat ini, atau tak berefek / memperburuk?"},
{n:43,type:"mcq",micro:"Gerakan untuk melepas energi",q:"Untuk emosi dengan banyak 'energi' (marah, cemas), gerakan yang bisa membantu:",options:["Berjalan cepat, berlari kecil, melompat, memukul bantal, atau meremas bola stres, memberi jalan keluar aman untuk energi itu","Duduk diam & menahan semua energi di dalam","Menghancurkan barang berharga"],answer:0,explain:"Emosi kuat sering datang dengan energi fisik. Menyalurkannya lewat gerakan yang tidak merugikan lebih sehat daripada menahannya atau merusak.",hint:"Gerakan yang aman untuk melepas energi, atau menahan di dalam / merusak barang?"},
{n:44,type:"mcq",micro:"Musik untuk mengelola suasana hati",q:"Musik bisa dipakai untuk mengelola emosi dengan cara...",options:["Musik tidak berpengaruh pada emosi","Memilih musik yang menenangkan saat cemas, atau musik yang perlahan mengangkat suasana hati saat sedih, secara sadar & sesuai kebutuhan","Selalu mendengarkan musik yang paling keras & intens"],answer:1,explain:"Memilih musik dengan sengaja (bukan sekadar apa yang muncul) bisa jadi alat yang efektif untuk menuntun suasana hati.",hint:"Pilih musik sesuai kebutuhan secara sadar, atau selalu keras / tak berpengaruh?"},
{n:45,type:"tf",micro:"Alam & ketenangan",q:"Benar atau Salah: Menghabiskan waktu di alam atau melihat pemandangan hijau tidak berpengaruh apa pun pada pikiran & suasana hati.",answer:false,explain:"Sebaliknya, banyak orang menemukan bahwa waktu di alam (taman, halaman, dekat pohon atau air) mengurangi ketegangan & membantu perasaan lebih tenang & jernih.",hint:"Bisa membantu menenangkan, atau tak berpengaruh?"},
{n:46,type:"mcq",micro:"Menulis surat yang tidak dikirim",q:"Menulis surat berisi semua yang ingin kamu katakan pada seseorang (yang membuatmu marah/terluka) TANPA mengirimnya berguna karena...",options:["Selalu harus dikirim agar berguna","Tidak ada gunanya kalau tidak dikirim","Membantu 'mengeluarkan' & memproses perasaan sepenuhnya tanpa risiko merusak hubungan atau menyesali kata-kata"],answer:2,explain:"Menulis untuk melepaskan (bukan untuk dikirim) adalah cara aman memproses emosi kuat sebelum memutuskan bagaimana benar-benar berkomunikasi.",hint:"Membantu memproses tanpa risiko, atau harus dikirim / tak berguna?"},
{n:47,type:"mcq",micro:"Aktivitas yang menyerap perhatian",q:"Melakukan aktivitas yang butuh fokus (menggambar, memasak, menyusun puzzle, olahraga) saat emosi kuat bisa membantu karena...",options:["Memberi pikiran 'istirahat' dari memutar-mutar masalah, & sering saat kembali, perasaannya sudah sedikit mereda & pikiran lebih jernih","Berarti kita menghindari masalah selamanya","Tidak boleh dilakukan karena mengabaikan perasaan"],answer:0,explain:"Pengalihan sementara yang sehat berbeda dari penghindaran permanen. Memberi jeda pada pikiran lalu kembali menghadapi masalah adalah pengelolaan yang seimbang.",hint:"Memberi pikiran istirahat sementara, atau menghindar selamanya / mengabaikan perasaan?"},
{n:48,type:"mcq",micro:"Berbicara dengan orang tepercaya",q:"Waktu yang tepat untuk bercerita ke orang tepercaya tentang emosi:",options:["Tidak pernah, semua harus ditangani sendiri","Bisa saat sedang kesulitan (untuk dukungan), atau setelah agak tenang (untuk memproses & mencari pendapat); yang penting orangnya membuatmu merasa aman","Hanya saat sedang di puncak emosi paling kuat"],answer:1,explain:"Kadang kita butuh didengar saat sedang berat; kadang butuh perspektif setelah tenang. Keduanya sah, sesuai kebutuhan saat itu.",hint:"Saat kesulitan atau setelah tenang, sesuai kebutuhan, atau hanya di puncak / tak pernah?"},
{n:49,type:"mcq",micro:"Rutinitas menenangkan",q:"Membangun rutinitas kecil yang menenangkan (mis. teh hangat & musik pelan setelah hari yang berat, atau peregangan sebelum tidur) berguna karena...",options:["Membuat hidup jadi terlalu terjadwal & kaku","Tidak ada manfaatnya","Memberi 'jangkar' yang bisa diandalkan untuk menurunkan ketegangan secara teratur, sebelum menumpuk jadi besar"],answer:2,explain:"Rutinitas menenangkan yang teratur membantu 'membuang' ketegangan sehari-hari sebelum ia menumpuk jadi ledakan.",hint:"Jangkar teratur untuk menurunkan ketegangan, atau terlalu kaku / tak bermanfaat?"},
{n:50,type:"order",micro:"Mengelola emosi seputar situasi sulit",q:"Urutkan langkah mengelola emosi untuk situasi yang kamu tahu akan sulit (mis. presentasi besok).",items:["Sebelumnya: akui perasaan ('aku akan gugup, itu wajar') & latih teknik menenangkan diri saat tenang","Sebelumnya: bersiap sebaik mungkin (latihan, persiapan) untuk mengurangi hal yang bisa dikendalikan","Saat itu: pakai teknik cepat (napas, self-talk mendukung) saat emosi terasa memuncak","Sesudah: proses perasaan (menulis/bicara) & rawat diri, apa pun hasilnya"],answer:[0,1,2,3],explain:"Akui & latih dulu → bersiap → teknik cepat saat itu → proses & rawat diri sesudah. Pengelolaan menyeluruh, bukan hanya bereaksi di tengah situasi.",hint:"Melatih teknik menenangkan diri dilakukan saat tenang sebelumnya, atau baru saat emosi memuncak?"},
{n:51,type:"mcq",micro:"Self-talk yang mendukung",q:"Contoh self-talk yang mendukung (bukan menyangkal kesulitan) saat menghadapi tantangan:",options:["'Ini sulit & aku gugup, tapi aku sudah bersiap & bisa melewatinya langkah demi langkah'","'Ini gampang banget, nggak usah dipikir' (menyangkal kesulitan)","'Aku pasti gagal total, percuma'"],answer:0,explain:"Self-talk yang baik mengakui kenyataan (ini sulit) sambil menambahkan dukungan (aku bisa mencoba), bukan menyangkal atau menghancurkan.",hint:"Mengakui sulit + mendukung, atau menyangkal kesulitan / menghancurkan?"},
{n:52,type:"tf",micro:"Latihan saat tenang penting",q:"Benar atau Salah: Cukup tahu teknik menenangkan diri secara teori; tidak perlu melatihnya saat tenang karena bisa langsung dipakai saat panik.",answer:false,explain:"Sebaliknya, seperti latihan kebakaran, kita perlu berlatih saat aman agar teknik jadi otomatis. Teknik yang belum pernah dilatih sulit diakses saat panik.",hint:"Latihan saat tenang membantu, atau hanya perlu tahu tekniknya saat butuh?"},
{n:53,type:"mcq",micro:"Menyesuaikan alat dengan emosi",q:"Alat menenangkan diri yang cocok bisa berbeda tergantung emosinya, misalnya...",options:["Tidak ada perbedaan, coba saja acak","Untuk marah (banyak energi): gerakan fisik. Untuk cemas (pikiran berputar): grounding & napas. Untuk sedih (energi rendah): dukungan orang & kelembutan pada diri","Satu alat yang sama cocok untuk semua emosi"],answer:1,explain:"Mengenali jenis emosi membantu memilih alat yang paling pas, marah butuh penyaluran energi, cemas butuh menenangkan pikiran, sedih butuh kelembutan.",hint:"Alat berbeda untuk emosi berbeda, atau satu alat untuk semua?"},
{n:54,type:"mcq",micro:"Mengelola emosi tanpa menyakiti orang lain",q:"Saat sangat marah pada seseorang, cara mengelola yang tidak merugikan hubungan:",options:["Langsung menyampaikan semua kemarahan dengan kata-kata tajam selagi panas","Memendam selamanya & tidak pernah menyampaikan apa pun","Menenangkan diri dulu (jeda, napas), lalu menyampaikan perasaan & keberatan dengan tenang & jelas setelah lebih tenang"],answer:2,explain:"Menyampaikan keberatan itu penting, tapi caranya (tenang, jelas, setelah agak reda) menentukan apakah masalahnya terselesaikan atau bertambah.",hint:"Tenangkan diri lalu sampaikan dengan tenang, atau langsung tajam selagi panas / memendam?"},
{n:55,type:"mcq",micro:"Mengelola kekecewaan",q:"Saat kecewa karena sesuatu tidak terjadi seperti harapan (tidak menang lomba, rencana batal), pengelolaan yang sehat:",options:["Izinkan diri merasa kecewa sejenak (tidak menyangkal), lalu perlahan alihkan energi ke apa yang masih bisa dilakukan atau dinikmati","Berpura-pura tidak kecewa sama sekali","Berkubang dalam kekecewaan tanpa henti selama berhari-hari"],answer:0,explain:"Mengakui kekecewaan lalu perlahan bergerak maju (bukan menyangkal maupun terjebak selamanya) adalah keseimbangan yang sehat.",hint:"Rasakan sejenak lalu alihkan ke yang masih bisa, atau menyangkal / berkubang tanpa henti?"},
{n:56,type:"tf",micro:"Meminta bantuan adalah strategi yang sah",q:"Benar atau Salah: Meminta bantuan orang lain untuk mengelola emosi yang berat berarti kita gagal mengelolanya sendiri & itu tanda kelemahan.",answer:false,explain:"Sebaliknya, manusia dirancang untuk saling mendukung. Meminta bantuan (teman, keluarga, guru, konselor) adalah salah satu strategi mengelola emosi yang sah & sering paling efektif, bukan kegagalan.",hint:"Strategi yang sah & efektif, atau tanda tak bisa mandiri?"},
{n:57,type:"mcq",micro:"Menghindari melampiaskan ke orang lain",q:"Kalau kamu marah karena satu hal lalu jadi ketus pada orang lain yang tidak bersalah ('melampiaskan'), langkah memperbaikinya:",options:["Terus melampiaskan karena sudah terlanjur","Sadari yang terjadi, minta maaf pada orang itu, & salurkan kemarahan aslinya lewat cara yang lebih tepat","Anggap wajar karena 'sedang emosi'"],answer:1,explain:"Melampiaskan ke orang yang salah adalah hal yang kadang terjadi, tapi mengakuinya & memperbaikinya (minta maaf, salurkan dengan benar) penting.",hint:"Sadari, minta maaf, & salurkan dengan tepat, atau anggap wajar / terus melampiaskan?"},
{n:58,type:"mcq",micro:"Menerima naik-turun",q:"Kalau setelah beberapa hari mengelola emosi dengan baik, kamu 'terpeleset' & bereaksi buruk lagi, sikap yang membangun:",options:["Simpulkan bahwa semua usaha sia-sia & berhenti mencoba","Menghukum diri sendiri secara berlebihan","Anggap sebagai bagian normal dari belajar; refleksikan apa yang bisa berbeda, minta maaf bila perlu, & lanjutkan tanpa menyerah"],answer:2,explain:"Mengelola emosi adalah keterampilan yang dilatih seumur hidup. 'Terpeleset' sesekali normal & bukan alasan menyerah.",hint:"Refleksi & lanjut tanpa menyerah, atau simpulkan sia-sia / hukum diri?"},
{n:59,type:"mcq",micro:"Membantu teman menenangkan diri",q:"Kalau temanmu sedang sangat emosi & kewalahan, cara membantu:",options:["Tetap tenang, bicara pelan, tanyakan apa yang ia butuhkan, & tawarkan hal sederhana (duduk bersama, minum air, jalan sebentar); jangan memaksanya 'tenang' atau menghakimi","Menyuruhnya 'tenang!' dengan nada tinggi","Ikut panik atau marah bersamanya"],answer:0,explain:"Kehadiran yang tenang & tidak menghakimi sering lebih membantu daripada nasihat atau perintah untuk tenang. Menyuruh 'tenang' biasanya justru tidak membantu.",hint:"Tetap tenang & tawarkan hal sederhana, atau menyuruh 'tenang' / ikut panik?"},
{n:60,type:"open",micro:"Rancang rencana mengelola satu emosi tertentu",q:"Pilih satu emosi yang paling sering kamu kesulitan mengelolanya (marah, cemas, sedih, malu, dll). Rancang rencana khusus: (a) tanda-tanda awal (tubuh & pikiran) bahwa emosi ini mulai muncul, (b) 2 hal yang akan kamu lakukan segera saat mengenali tanda itu, (c) 1 hal yang akan kamu lakukan untuk memproses setelah puncaknya lewat, (d) 1 kebiasaan sehari-hari yang akan membantumu lebih tahan menghadapi emosi ini, (e) kapan kamu akan mencari bantuan orang lain.",sample:"Emosi: kecemasan. (a) Tanda-tanda awal: di tubuh, perut terasa mengganjal, napas jadi lebih pendek & dangkal, bahu naik & tegang, telapak tangan agak berkeringat. Di pikiran, aku mulai berpikir 'bagaimana kalau...' berulang-ulang & membayangkan skenario terburuk. (b) Yang kulakukan segera: (1) Napas kotak 4-4-4-4 sebanyak 4-6 kali sambil menurunkan bahu dengan sadar. (2) Grounding, menyebutkan 5 hal yang kulihat & menekan kedua kaki ke lantai, memperhatikan sensasinya, untuk membawa perhatian keluar dari pikiran yang berputar. (c) Memproses setelah puncaknya lewat: menulis di buku catatan selama 10 menit, apa yang sebenarnya kucemaskan, apa yang bisa & tidak bisa kukendalikan, & satu langkah kecil yang bisa kulakukan untuk hal yang bisa kukendalikan. (d) Kebiasaan sehari-hari: tidur cukup (target 8 jam) & berjalan/bergerak minimal 20 menit setiap hari, karena aku sadar kecemasanku jauh lebih mudah muncul & lebih sulit ditenangkan saat aku kurang tidur atau tidak bergerak seharian. (e) Kapan mencari bantuan: kalau kecemasan mulai membuatku menghindari kegiatan yang sebenarnya ingin kulakukan, kalau berlangsung hampir setiap hari selama lebih dari dua minggu, atau kalau teknik-teknik ini terasa tidak lagi cukup membantu, aku akan bicara dengan ibuku & wali kelas, & terbuka bahwa aku mungkin butuh bicara dengan konselor sekolah.",explain:"Jawaban baik: tanda awal yang spesifik untuk tubuh & pikiran, 2 tindakan segera yang cocok untuk jenis emosinya (mis. napas & grounding untuk cemas, gerakan untuk marah), 1 cara memproses setelahnya, 1 kebiasaan fondasi yang relevan, & kriteria konkret kapan mencari bantuan dengan rencana bicara ke siapa.",hint:"Sesuaikan tindakan (b) dengan jenis emosinya: cemas butuh menenangkan pikiran, marah butuh menyalurkan energi, sedih butuh kelembutan & dukungan."},

// FASE D — PENALARAN (61-80): batas, coping tidak sehat, keseimbangan
{n:61,type:"mcq",micro:"Mengelola bukan menghilangkan emosi",q:"Tujuan mengelola emosi yang sehat adalah...",options:["Selalu terlihat tenang di luar dengan menahan semuanya di dalam","Bisa merasakan emosi (termasuk yang sulit) tanpa dikuasai olehnya, & tetap bisa berpikir & bertindak sesuai nilai kita","Tidak pernah lagi merasakan emosi yang tidak menyenangkan"],answer:1,explain:"Orang yang sehat secara emosi tetap merasakan seluruh rentang emosi; mereka hanya lebih mampu pulih & memilih respons.",hint:"Merasakan tanpa dikuasai, atau tak pernah merasa sulit / menahan semua?"},
{n:62,type:"mcq",micro:"Coping tidak sehat yang perlu diwaspadai",q:"Cara 'menenangkan diri' yang bisa merugikan bila jadi kebiasaan utama:",options:["Menarik napas & mengambil jeda","Bicara dengan orang tepercaya","Selalu menghindari, terus-menerus melampiaskan ke orang lain, mengurung diri total dari semua orang, atau mengabaikan kebutuhan dasar (tidak makan/tidur)"],answer:2,explain:"Cara-cara ini mungkin memberi kelegaan sesaat, tapi tidak menyelesaikan masalah & bisa menimbulkan masalah baru bila jadi pola utama.",hint:"Menghindari total / melampiaskan / abaikan kebutuhan, atau napas & bicara?"},
{n:63,type:"mcq",micro:"Menyeimbangkan mengekspresikan & menahan",q:"Selalu menahan semua emosi (tidak pernah mengekspresikan) & selalu mengekspresikan semua emosi tanpa filter (meledak di mana saja), keduanya...",options:["Punya masalahnya sendiri; yang sehat adalah keseimbangan, mengekspresikan dengan cara & di tempat yang sesuai","Sama-sama baik, tinggal pilih","Menahan selalu lebih baik daripada mengekspresikan"],answer:0,explain:"Menahan total bisa membuat emosi menumpuk & tubuh tegang; mengekspresikan tanpa filter bisa merusak hubungan. Keseimbangan yang tepat berada di antaranya.",hint:"Keseimbangan mengekspresikan dengan tepat, atau salah satu ekstrem?"},
{n:64,type:"tf",micro:"Kapan strategi mandiri tidak cukup",q:"Benar atau Salah: Kalau seseorang sudah mencoba berbagai strategi mengelola emosi tapi perasaan berat tetap mengganggu tidur, sekolah, makan, atau hubungan dalam waktu lama, itu tanda untuk mencari dukungan lebih (orang dewasa tepercaya, konselor, profesional).",answer:true,explain:"Sebagian perasaan memang lebih dari yang bisa ditangani sendirian, & mencari bantuan yang tepat adalah langkah bijak & berani, bukan kegagalan.",hint:"Tanda untuk mencari dukungan lebih, atau harus terus sendiri?"},
{n:65,type:"mcq",micro:"Mengelola emosi & pola pikir",q:"Cara berpikir yang membantu pengelolaan emosi jangka panjang:",options:["Menganggap kemampuan mengelola emosi sebagai bakat tetap yang tidak bisa dilatih","Melihat emosi sebagai bagian normal & informatif dari hidup, & kemampuan mengelolanya sebagai sesuatu yang terus tumbuh dengan latihan","Menganggap emosi sebagai musuh yang harus dikalahkan setiap kali"],answer:1,explain:"Pola pikir 'ini bisa dilatih & emosi bukan musuh' membuat kita lebih sabar pada diri sendiri & lebih tekun berlatih.",hint:"Emosi normal & kemampuan tumbuh dengan latihan, atau emosi musuh / bakat tetap?"},
{n:66,type:"mcq",micro:"Emosi orang lain & batas kita",q:"Saat berada di sekitar orang yang sering beremosi kuat, menjaga keseimbangan diri berarti...",options:["Wajib menanggung sepenuhnya semua perasaan orang di sekitar","Tidak peduli sama sekali pada perasaan orang lain","Bisa peduli & mendukung, tapi tidak menyerap semua emosi mereka sampai kewalahan sendiri; menjaga batas itu sehat, bukan egois"],answer:2,explain:"Empati yang berkelanjutan butuh menjaga diri juga. Menetapkan batas ('aku mau membantu, tapi aku juga butuh waktu untuk diriku') adalah keseimbangan yang sehat.",hint:"Dukung tanpa menyerap semua sampai kewalahan, atau tanggung semua / tak peduli?"},
{n:67,type:"mcq",micro:"Mengenali coping yang jadi masalah",q:"Kalau kamu menyadari 'cara menenangkan diri'-mu mulai menimbulkan masalah sendiri (mis. selalu menghindar sampai tertinggal pelajaran, atau selalu marah ke orang lain), langkah yang bijak:",options:["Akui pola itu, cari alternatif yang lebih sehat, & bila sulit mengubahnya sendiri, bicara dengan orang dewasa tepercaya","Terus lakukan karena 'itu satu-satunya yang membantu'","Menyembunyikannya karena malu"],answer:0,explain:"Mengenali bahwa strategi kita sendiri jadi bermasalah & mencari yang lebih baik (dengan bantuan bila perlu) adalah bagian dari mengelola emosi yang matang.",hint:"Akui, cari alternatif, & minta bantuan bila sulit, atau terus / sembunyikan?"},
{n:68,type:"tf",micro:"Belas kasih pada diri sendiri membantu",q:"Benar atau Salah: Memperlakukan diri sendiri dengan kebaikan & pengertian saat sedang kesulitan (bukan dengan kritik keras) sebenarnya membuat kita lebih mampu pulih & mencoba lagi, bukan membuat kita 'manja'.",answer:true,explain:"Penelitian & pengalaman menunjukkan bahwa self-compassion (belas kasih pada diri) meningkatkan ketahanan & motivasi, sementara kritik diri yang keras sering justru melumpuhkan.",hint:"Membantu pulih & mencoba lagi, atau membuat manja?"},
{n:69,type:"mcq",micro:"Emosi & keputusan sehari-hari",q:"Menyadari 'aku sedang beremosi kuat, sebaiknya aku tunda keputusan penting' adalah bentuk...",options:["Penghindaran yang tidak bertanggung jawab","Kebijaksanaan emosi, mengenali kapan kondisi kita kurang ideal untuk memutuskan & memberi ruang untuk itu","Kelemahan, karena 'orang kuat memutuskan kapan saja'"],answer:1,explain:"Mengenali kapan kita tidak dalam kondisi terbaik untuk memutuskan (& menundanya) adalah tanda kematangan, bukan kelemahan atau penghindaran.",hint:"Kebijaksanaan mengenali kondisi, atau kelemahan / penghindaran?"},
{n:70,type:"tf",micro:"Mengelola emosi mendukung hubungan",q:"Benar atau Salah: Orang yang mampu menenangkan diri & menyampaikan perasaan dengan tenang cenderung punya hubungan yang lebih sehat, karena konflik lebih jarang berubah jadi luka yang dalam.",answer:true,explain:"Cara kita mengelola emosi saat konflik sangat memengaruhi apakah masalah terselesaikan atau justru merusak hubungan.",hint:"Mendukung hubungan yang lebih sehat, atau tak berhubungan?"},
{n:71,type:"mcq",micro:"Emosi & rasa syukur",q:"Sengaja memperhatikan hal-hal baik & momen tenang dalam hidup membantu pengelolaan emosi karena...",options:["Berarti mengabaikan masalah yang nyata","Membuat kita tidak realistis","Melatih pikiran untuk juga menangkap yang positif, menyeimbangkan kecenderungan alami untuk lebih fokus pada ancaman & masalah"],answer:2,explain:"Ini bukan mengabaikan masalah, tapi menyeimbangkan perhatian kita agar tidak hanya melihat yang buruk, yang membantu suasana hati secara keseluruhan.",hint:"Menyeimbangkan perhatian, atau mengabaikan masalah / jadi tak realistis?"},
{n:72,type:"mcq",micro:"Emosi kuat & fungsi otak",q:"Saat emosi sangat kuat, kemampuan berpikir jernih & mempertimbangkan pilihan...",options:["Sementara menurun; ini kenapa 'menenangkan diri dulu' bukan sekadar saran tapi hal yang benar-benar membantu otak kembali berfungsi optimal","Tetap sama seperti saat tenang","Justru meningkat karena 'lebih fokus'"],answer:0,explain:"Ini alasan biologis kenapa jeda & menenangkan diri penting sebelum menghadapi masalah atau membuat keputusan, bukan sekadar 'agar terlihat kalem'.",hint:"Sementara menurun, atau tetap sama / meningkat?"},
{n:73,type:"mcq",micro:"Mengelola emosi bukan tugas sekali selesai",q:"Kemampuan mengelola emosi...",options:["Adalah bakat yang dimiliki sejak lahir atau tidak sama sekali","Terus berkembang seumur hidup; ada situasi & tantangan baru yang menuntut kita terus belajar, bahkan bagi orang dewasa","Selesai dipelajari di usia tertentu lalu tidak perlu dipikirkan lagi"],answer:1,explain:"Setiap fase hidup membawa emosi & situasi baru. Mengelola emosi adalah keterampilan yang terus diasah, bukan yang 'lulus' sekali.",hint:"Berkembang seumur hidup, atau selesai di usia tertentu / bakat tetap?"},
{n:74,type:"mcq",micro:"Menghormati proses orang lain",q:"Kalau orang lain butuh waktu lebih lama untuk menenangkan diri atau memakai cara yang berbeda dari kita, sikap yang menghormati:",options:["Menganggap cara kita yang paling benar & mereka harus mengikutinya","Menghakimi mereka karena 'terlalu lama' atau 'aneh'","Menerima bahwa setiap orang punya ritme & cara berbeda; tidak memaksakan cara atau kecepatan kita pada mereka"],answer:2,explain:"Tidak ada satu cara 'benar' mengelola emosi. Menghormati keberagaman ini penting dalam hubungan.",hint:"Menerima ritme & cara berbeda, atau memaksakan cara kita / menghakimi?"},
{n:75,type:"order",micro:"Menilai apakah cara coping-mu sehat",q:"Urutkan langkah menilai apakah cara-cara menenangkan dirimu sehat atau perlu diubah.",items:["Daftar cara-cara yang biasanya kamu pakai saat emosi kuat","Untuk masing-masing, tanya: apakah ini merugikan diriku, orang lain, atau menghindari masalah selamanya?","Tandai yang bermasalah & cari alternatif yang lebih sehat untuk menggantikannya","Bila sulit mengubah sendiri (mis. yang sudah jadi kebiasaan kuat), bicara dengan orang dewasa tepercaya"],answer:[0,1,2,3],explain:"Daftar → nilai dampaknya → ganti yang bermasalah → minta bantuan bila sulit. Menilai kejujuran dampak setiap cara, bukan hanya 'apakah terasa lega'.",hint:"Menandai cara yang bermasalah dilakukan sebelum atau sesudah menilai dampaknya?"},
{n:76,type:"tf",micro:"Emosi kuat bukan tanda ada yang salah dengan kita",q:"Benar atau Salah: Merasakan emosi yang kuat sesekali (sangat marah, sangat sedih, sangat cemas) adalah bagian normal dari menjadi manusia, bukan tanda bahwa ada yang 'rusak' pada diri kita.",answer:true,explain:"Yang lebih penting untuk diperhatikan bukan 'apakah aku merasakan emosi kuat' tapi 'apakah perasaan berat ini berlangsung sangat lama & sangat mengganggu hidupku'.",hint:"Bagian normal manusia, atau tanda ada yang rusak?"},
{n:77,type:"mcq",micro:"Mengelola emosi & merawat orang lain",q:"Orang yang bisa mengelola emosinya sendiri dengan baik biasanya juga lebih mampu...",options:["Menemani & mendukung orang lain yang sedang kesulitan tanpa ikut kewalahan atau panik","Mengabaikan perasaan orang lain sepenuhnya","Membuat semua orang di sekitarnya juga tidak boleh beremosi"],answer:0,explain:"Ketenangan kita bisa 'menular' dengan cara yang membantu, kehadiran yang stabil membantu orang lain yang sedang kalut.",hint:"Lebih mampu mendukung tanpa kewalahan, atau mengabaikan / melarang emosi orang lain?"},
{n:78,type:"mcq",micro:"Emosi & identitas",q:"Mengatakan 'aku sedang kesulitan mengelola kemarahanku belakangan ini' berbeda dari 'aku adalah orang yang pemarah' karena...",options:["'Aku adalah' selalu lebih jujur","Yang pertama menggambarkan keadaan sementara yang bisa diubah; yang kedua menjadikannya identitas tetap yang terasa sulit diubah","Keduanya sama saja"],answer:1,explain:"Bahasa yang kita pakai memengaruhi harapan kita. Melihat kesulitan sebagai 'sesuatu yang sedang kualami & bisa kupelajari' lebih memberdayakan.",hint:"Keadaan sementara yang bisa diubah, atau identitas tetap?"},
{n:79,type:"mcq",micro:"Menyeimbangkan mengelola & menjalani hidup",q:"Kalau kamu jadi terlalu fokus 'harus selalu mengelola emosi dengan sempurna' sampai stres sendiri, sikap yang lebih sehat:",options:["Menuntut kesempurnaan & menghukum diri setiap kali gagal","Menyerah total dan tidak lagi mencoba mengelola apa pun","Ingat bahwa mengelola emosi adalah alat untuk hidup lebih baik, bukan ujian yang harus dilalui sempurna; 'cukup baik' & terus belajar sudah bagus"],answer:2,explain:"Perfeksionisme dalam mengelola emosi bisa jadi sumber stres baru. Tujuannya adalah hidup yang lebih baik, bukan nilai sempurna.",hint:"'Cukup baik' & terus belajar, atau menuntut sempurna / menyerah total?"},
{n:80,type:"open",micro:"Membedakan coping sehat & tidak sehat",q:"Bayangkan seorang teman yang, setiap kali marah atau kesal, selalu langsung mengurung diri di kamar seharian tanpa bicara ke siapa pun, membatalkan semua rencana, & tidak makan sampai malam; ia bilang 'ini caraku menenangkan diri'. Analisis: (a) mana bagian yang bisa jadi sehat & mana yang jadi tidak sehat, jelaskan alasannya, (b) alternatif yang lebih sehat yang bisa kamu sarankan, (c) bagaimana kamu akan menyampaikan kepedulianmu tanpa menghakimi, (d) kapan menurutmu situasi ini perlu perhatian orang dewasa.",sample:"(a) Bagian yang bisa sehat, mengambil jeda & waktu sendiri untuk menenangkan diri saat marah adalah hal yang baik, tidak semua orang harus langsung bicara. Bagian yang jadi tidak sehat, (1) mengurung diri SEHARIAN tanpa kontak dengan siapa pun terlalu lama, bisa membuat pikiran negatif berputar tanpa ada yang menyeimbangkan; (2) membatalkan SEMUA rencana setiap kali, membuat emosi mengendalikan hidupnya & bisa merusak hubungan/tanggung jawab; (3) tidak makan sampai malam, mengabaikan kebutuhan dasar tubuh justru membuat emosi lebih sulit ditenangkan (lapar memperburuk suasana hati). Jadi masalahnya bukan 'menenangkan diri sendiri' tapi bentuknya yang ekstrem & mengorbankan hal-hal penting. (b) Alternatif yang lebih sehat, ambil jeda 30-60 menit di kamar (bukan seharian), lakukan sesuatu yang menyalurkan energi (jalan kaki, menulis, dengar musik), tetap makan meski sedikit, & setelah lebih tenang, kembali ke rencana atau setidaknya mengabari orang bila perlu membatalkan; bila masih berat, bicara dengan satu orang tepercaya. (c) Menyampaikan kepedulian tanpa menghakimi, 'Aku perhatiin belakangan ini kalau kamu kesal, kamu suka menghilang seharian & nggak makan. Aku nggak mau maksa kamu cerita, cuma aku agak khawatir. Kalau kamu mau ditemani atau butuh apa-apa, aku ada ya.' (d) Kapan perlu perhatian orang dewasa, kalau pola ini terjadi sangat sering (hampir setiap minggu), kalau ia mulai menarik diri dari hampir semua orang & kegiatan secara terus-menerus, kalau tidak makannya berlangsung lama & sering, atau kalau aku melihat tanda ia merasa sangat putus asa, maka aku akan mendorongnya bicara ke orang tua/konselor & bila ia menolak sementara aku sangat khawatir, aku sendiri akan bicara ke orang dewasa tepercaya karena ini di luar kemampuanku sebagai teman untuk menangani sendirian.",explain:"Jawaban baik: analisis yang membedakan inti yang sehat (mengambil jeda) dari bentuk yang jadi tidak sehat (durasi ekstrem, membatalkan semua, mengabaikan kebutuhan dasar) dengan alasan yang jelas, alternatif konkret yang lebih seimbang, cara menyampaikan kepedulian yang tidak menghakimi & tidak memaksa, & kriteria yang jelas kapan melibatkan orang dewasa (frekuensi, penarikan diri menyeluruh, tanda putus asa).",hint:"Kuncinya: 'menenangkan diri sendiri' itu sehat, tapi menjadi tidak sehat kalau bentuknya ekstrem, mengorbankan kebutuhan dasar, & membuat emosi mengendalikan hidup."},

// FASE E — TANTANGAN (81-100): skenario & kapstone
{n:81,type:"mcq",micro:"Skenario: hampir membalas pesan dengan marah",q:"Kamu menerima pesan yang membuatmu sangat marah & jarimu sudah siap mengetik balasan tajam. Langkah terbaik saat itu:",options:["Letakkan HP, tarik napas beberapa kali, lakukan hal lain 15-30 menit, lalu putuskan dengan kepala lebih dingin apakah & bagaimana membalas","Kirim balasan tajam itu selagi 'jujur pada perasaan'","Blokir orangnya selamanya tanpa berpikir"],answer:0,explain:"Balasan yang ditulis di puncak kemarahan hampir selalu berbeda (& sering lebih menyakiti) dari yang akan kamu tulis setelah tenang. Jeda melindungi hubungan & dirimu.",hint:"Letakkan HP & tunda, atau kirim tajam selagi 'jujur' / blokir tanpa pikir?"},
{n:82,type:"mcq",micro:"Skenario: cemas berat sebelum ujian",q:"Malam sebelum ujian besar, kamu merasa sangat cemas sampai sulit fokus belajar & sulit tidur. Kombinasi respons yang membantu:",options:["Menyerah belajar sama sekali & 'pasrah'","Napas & grounding untuk menenangkan tubuh, belajar dalam potongan kecil dengan jeda, self-talk yang mengakui kesulitan tapi mendukung, & memastikan tetap tidur cukup","Belajar semalaman tanpa tidur karena panik"],answer:1,explain:"Cemas berat butuh menenangkan tubuh + strategi belajar yang realistis + menjaga tidur, karena kurang tidur akan memperburuk kecemasan & performa besok.",hint:"Tenangkan tubuh + belajar bertahap + jaga tidur, atau begadang panik / menyerah?"},
{n:83,type:"mcq",micro:"Skenario: sedih mendalam setelah kehilangan",q:"Setelah kehilangan sesuatu yang berarti (hewan peliharaan, pindahnya sahabat, kegagalan besar), kamu merasa sangat sedih berhari-hari. Sikap yang sehat:",options:["Memaksa diri 'move on' segera & menekan kesedihan","Menyimpannya sepenuhnya sendiri tanpa cerita ke siapa pun","Izinkan diri berduka (kesedihan setelah kehilangan itu wajar & butuh waktu), cari dukungan dari orang tepercaya, & bila terasa sangat berat & berkepanjangan, bicara dengan orang dewasa"],answer:2,explain:"Berduka adalah proses yang butuh waktu & dukungan. Menekannya atau menghadapinya sendirian sepenuhnya sering membuat prosesnya lebih berat.",hint:"Izinkan berduka + cari dukungan + bicara ke dewasa bila berat, atau paksa move on / pendam sendiri?"},
{n:84,type:"mcq",micro:"Skenario: teman menyuruhmu 'tenang' saat kamu emosi",q:"Saat kamu sedang emosi, temanmu berkata 'udah, tenang aja, nggak usah lebay'. Respons yang menjaga dirimu:",options:["Katakan dengan jujur apa yang kamu butuhkan ('aku butuh waktu sebentar' atau 'aku cuma butuh didengar dulu, bukan dinasihati'), & tetap lakukan cara menenangkan dirimu sendiri","Menuruti & memaksa diri 'tenang' padahal belum siap","Marah lebih besar pada temanmu"],answer:0,explain:"Menyuruh seseorang 'tenang' jarang membantu. Kamu berhak menyampaikan apa yang sebenarnya kamu butuhkan & tetap memakai cara menenangkan diri yang cocok untukmu.",hint:"Sampaikan kebutuhanmu & lakukan caramu, atau paksa 'tenang' / marah lebih besar?"},
{n:85,type:"tf",micro:"Mengelola emosi adalah keterampilan hidup penting",q:"Benar atau Salah: Kemampuan menenangkan diri & mengelola emosi berperan besar dalam keberhasilan belajar, kualitas hubungan, pengambilan keputusan, & kesejahteraan sepanjang hidup.",answer:true,explain:"Keterampilan ini adalah bagian inti dari kecerdasan emosi & berpengaruh luas pada hampir semua aspek kehidupan.",hint:"Berperan besar & luas manfaatnya, atau hanya soal 'kalem'?"},
{n:86,type:"mcq",micro:"Skenario: emosi memuncak di tempat umum",q:"Kamu merasa emosi akan meledak saat berada di tempat ramai (mal, sekolah, angkot). Langkah yang bisa dilakukan diam-diam:",options:["Menahan mati-matian sampai pulang & meledak di rumah","Napas kotak secara diam-diam, tekan kaki ke lantai & rasakan sensasinya, hitung benda di sekitar, atau pindah ke tempat lebih tenang bila memungkinkan (toilet, sudut, luar ruangan)","Meledak di tempat itu karena 'sudah tidak tahan'"],answer:1,explain:"Banyak teknik menenangkan diri bisa dilakukan tanpa terlihat orang. Berpindah ke tempat lebih tenang sebentar juga pilihan yang sah.",hint:"Teknik diam-diam / pindah ke tempat tenang, atau meledak di sana / tahan sampai rumah?"},
{n:87,type:"mcq",micro:"Skenario: marah pada diri sendiri karena kesalahan",q:"Kamu membuat kesalahan yang merugikan orang lain & jadi sangat marah & keras pada diri sendiri ('aku bodoh, aku selalu merusak segalanya'). Cara mengelola yang lebih sehat:",options:["Terus menghukum diri sendiri sekeras mungkin agar 'tidak mengulanginya'","Menyangkal bahwa itu kesalahanmu","Akui kesalahannya & perbaiki bila bisa (minta maaf, tanggung jawab), lalu bicara pada diri seperti pada teman yang berbuat salah ('semua orang bikin kesalahan, yang penting kuperbaiki & kupelajari')"],answer:2,explain:"Kritik diri yang keras jarang mencegah kesalahan berulang; sering justru melumpuhkan. Bertanggung jawab + belas kasih pada diri = kombinasi yang membantu belajar & pulih.",hint:"Perbaiki + bicara pada diri seperti pada teman, atau hukum diri keras / menyangkal?"},
{n:88,type:"mcq",micro:"Skenario: emosi bertumpuk dari banyak hal kecil",q:"Kamu sadar hari ini kamu sangat mudah kesal karena banyak hal kecil menumpuk (kurang tidur + tugas banyak + berselisih dengan teman + lapar). Langkah yang tepat:",options:["Kenali bahwa 'wadahnya hampir penuh', penuhi kebutuhan dasar dulu (makan, istirahat, mungkin tidur lebih awal), & tunda membahas hal-hal berat sampai lebih pulih","Menyalahkan diri karena 'kok jadi sensitif banget'","Menyelesaikan semua masalah sekaligus sekarang selagi 'produktif'"],answer:0,explain:"Saat banyak hal menumpuk, merawat kebutuhan dasar & mengurangi beban sering lebih efektif daripada memaksa diri menyelesaikan semuanya di kondisi yang sudah kewalahan.",hint:"Penuhi kebutuhan dasar & kurangi beban, atau salahkan diri / selesaikan semua sekaligus?"},
{n:89,type:"mcq",micro:"Skenario: strategi biasanya berhasil tapi kali ini tidak",q:"Teknik menenangkan diri yang biasanya membantumu kali ini tidak terasa cukup, & emosi berat sudah berlangsung berhari-hari. Langkah yang bijak:",options:["Terus mencoba teknik yang sama sendirian sampai berhasil, seberapa lama pun","Jangan terus memaksakan sendiri; bicara dengan orang dewasa tepercaya, jelaskan apa yang kamu alami & bahwa strategi biasamu tidak cukup kali ini","Anggap dirimu gagal & berhenti mencoba apa pun"],answer:1,explain:"Mengenali kapan sebuah perasaan lebih besar dari yang bisa kita tangani sendiri, & mencari bantuan, adalah bagian dari mengelola emosi dengan bijak.",hint:"Bicara dengan orang dewasa tepercaya, atau anggap gagal / terus sendiri?"},
{n:90,type:"order",micro:"Proyek: melatih satu teknik selama sebulan",q:"Urutkan langkah proyek 'kuasai satu teknik menenangkan diri dalam sebulan'.",items:["Pilih satu teknik (mis. napas kotak) & pelajari cara melakukannya dengan benar","Latih setiap hari saat TIDAK sedang emosi (mis. 2 menit tiap pagi & malam) agar jadi otomatis","Pakai saat emosi mulai muncul & catat: apakah membantu? berapa lama sampai terasa efeknya?","Di akhir bulan, evaluasi: apakah teknik ini cocok untukmu, perlu penyesuaian, atau ganti teknik lain?"],answer:[0,1,2,3],explain:"Pelajari → latih rutin saat tenang → pakai saat emosi & catat → evaluasi. Latihan saat tenang adalah kunci agar teknik bisa diakses saat panik.",hint:"Melatih rutin saat tenang dilakukan sebelum atau sesudah memakainya saat emosi?"},
{n:91,type:"mcq",micro:"Skenario: konflik yang butuh dibahas tapi kamu masih emosi",q:"Ada masalah dengan temanmu yang perlu dibahas, tapi setiap kali kamu memikirkannya kamu jadi sangat marah lagi. Pendekatan yang matang:",options:["Ajak bicara sekarang juga selagi masih sangat marah agar 'tuntas'","Diamkan selamanya karena terlalu memicu emosi","Tenangkan diri & proses dulu (napas, menulis, mungkin bicara dengan orang lain untuk melihat lebih jernih), lalu ajak bicara temanmu saat kamu bisa menyampaikan dengan tenang & jelas"],answer:2,explain:"Masalah tetap perlu dibahas, tapi menunggu sampai kamu bisa menyampaikannya dengan tenang jauh lebih mungkin menyelesaikannya daripada memperbesarnya.",hint:"Proses dulu lalu bahas dengan tenang, atau bahas selagi marah / diamkan selamanya?"},
{n:92,type:"tf",micro:"Naik-turun adalah bagian dari belajar",q:"Benar atau Salah: Dalam belajar mengelola emosi, wajar mengalami hari-hari baik & hari-hari di mana kita 'terpeleset'; yang penting terus berlatih & belajar dari setiap pengalaman, bukan menyerah karena tidak sempurna.",answer:true,explain:"Kemajuan dalam mengelola emosi jarang berupa garis lurus. Kesabaran pada diri sendiri di sepanjang proses itu penting.",hint:"Naik-turun wajar & terus berlatih, atau harus sempurna atau menyerah?"},
{n:93,type:"mcq",micro:"Skenario: membantu adik yang tantrum",q:"Adik kecilmu sedang tantrum (menangis keras, berteriak) karena kecewa. Cara membantu:",options:["Tetap tenang, pastikan ia aman, bicara pelan, tunggu badainya sedikit mereda sebelum mencoba bicara panjang; jangan ikut berteriak atau menghukum saat puncak","Berteriak lebih keras darinya agar ia 'diam'","Mengabaikannya sepenuhnya sampai selesai sendiri tanpa memastikan ia aman"],answer:0,explain:"Anak kecil belum punya kemampuan menenangkan diri seperti orang lebih besar. Kehadiran yang tenang & sabar membantu, sementara berteriak balik atau menghukum di puncak memperburuk.",hint:"Tetap tenang, pastikan aman, tunggu mereda, atau berteriak balik / abaikan total?"},
{n:94,type:"mcq",micro:"Skenario: menyeimbangkan mengelola emosi & jujur pada perasaan",q:"Kamu takut kalau terlalu sering 'menenangkan diri' & 'menunda reaksi', kamu jadi tidak jujur pada perasaanmu atau jadi orang yang memendam. Cara menyeimbangkan:",options:["Selalu memendam demi terlihat 'bisa mengelola emosi'","Menenangkan diri untuk MEMILIH cara mengungkapkan perasaan dengan lebih baik, bukan untuk menghapus atau memendamnya; perasaan tetap disampaikan, hanya caranya lebih dipilih","Berhenti menenangkan diri & selalu bereaksi spontan agar 'jujur'"],answer:1,explain:"Mengelola emosi yang sehat TIDAK berarti memendam. Perasaan tetap diakui & disampaikan, tapi dengan cara & waktu yang lebih efektif.",hint:"Menenangkan diri untuk memilih cara menyampaikan, atau reaksi spontan selalu / selalu memendam?"},
{n:95,type:"tf",micro:"Menenangkan diri adalah kebaikan pada diri & orang lain",q:"Benar atau Salah: Meluangkan waktu untuk menenangkan diri sebelum merespons situasi sulit adalah bentuk kebaikan, baik pada diri sendiri (mengurangi penyesalan) maupun pada orang lain (mengurangi kata-kata & tindakan yang menyakiti).",answer:true,explain:"Jeda untuk menenangkan diri sering melindungi hubungan & harga diri kita sekaligus.",hint:"Kebaikan pada diri & orang lain, atau hanya menghindar?"},
{n:96,type:"mcq",micro:"Skenario: menjadi teladan mengelola emosi",q:"Adik/sepupu yang lebih muda mengamati bagaimana kamu menangani emosi. Cara menjadi teladan yang baik:",options:["Selalu berpura-pura tidak pernah beremosi","Meledak lalu menyuruh mereka 'jangan seperti kakak'","Tunjukkan secara terbuka: 'Aku lagi kesal nih, aku mau napas & jalan sebentar dulu ya' lalu praktikkan; ini mengajari mereka bahwa emosi wajar & ada cara sehat menanganinya"],answer:2,explain:"Anak belajar mengelola emosi dari melihat orang di sekitarnya melakukannya, mengakui emosi & menunjukkan cara sehat menanganinya adalah pengajaran yang kuat.",hint:"Tunjukkan cara sehat secara terbuka, atau berpura-pura tak beremosi / meledak?"},
{n:97,type:"mcq",micro:"Menilai pemahaman diri",q:"Tanda kamu sudah cukup terampil mengelola emosi:",options:["Kamu bisa mengenali emosi memuncak sebelum meledak, punya beberapa teknik yang cocok & bisa dipakai, bisa menunda reaksi untuk hal penting, & tahu kapan butuh bantuan","Kamu hafal semua teknik tapi tidak pernah memakainya saat emosi","Kamu tidak pernah lagi merasakan emosi apa pun"],answer:0,explain:"Keterampilan sejati terlihat dari kemampuan mengenali dini + punya alat yang dipakai + menunda reaksi + tahu batas, bukan hafalan atau 'mati rasa'.",hint:"Kenali dini + alat yang dipakai + menunda + tahu batas, atau hafal tanpa pakai / tak merasa?"},
{n:98,type:"mcq",micro:"Mengelola emosi & masyarakat",q:"Kelompok/keluarga/komunitas di mana orang bisa menenangkan diri & menyampaikan perasaan dengan sehat cenderung...",options:["Tidak berbeda dari kelompok yang penuh ledakan emosi","Menyelesaikan konflik dengan lebih baik, saling mendukung lebih efektif, & jadi tempat yang lebih aman bagi semua anggotanya","Menjadi lemah & tidak bisa menyelesaikan masalah"],answer:1,explain:"Cara sekelompok orang mengelola emosi secara kolektif sangat memengaruhi kualitas hubungan & kemampuan mereka menghadapi tantangan bersama.",hint:"Menyelesaikan konflik lebih baik & lebih aman, atau lemah / tak berbeda?"},
{n:99,type:"mcq",micro:"Inti keterampilan",q:"Inti dari 'mengelola emosi & menenangkan diri':",options:["Berusaha tidak pernah merasakan emosi & menahan semua","Selalu bertindak persis sesuai dorongan emosi saat itu juga","Kenali emosi yang muncul, tenangkan tubuh & pikiran dengan teknik yang cocok, beri jeda sebelum merespons hal penting, pilih tindakan yang sesuai nilaimu, & tahu kapan perasaan butuh dukungan lebih"],answer:2,explain:"Kenali + tenangkan + jeda + pilih respons + tahu batas. Ini bukan menghapus emosi, tapi bekerja sama dengannya untuk hidup yang lebih baik.",hint:"Kenali + tenangkan + jeda + pilih + tahu batas, atau menahan semua / ikuti dorongan?"},
{n:100,type:"open",micro:"Kapstone: rencana pengelolaan emosi pribadi",q:"Tulis rencana lengkap pengelolaan emosi pribadimu untuk dipegang seterusnya. Sertakan: (a) kotak alat menenangkan diri (minimal 2 teknik cepat + 2 kegiatan lebih panjang + orang tepercaya), (b) cara kamu mengenali emosi memuncak sebelum meledak (tanda tubuh & pikiran), (c) aturan pribadi tentang menunda reaksi untuk hal penting, (d) kebiasaan sehari-hari (tidur, gerak, dll) yang mendukung kemampuanmu mengelola emosi, (e) daftar orang & tanda-tanda yang memberi tahu kamu bahwa sebuah perasaan butuh dukungan lebih dari yang bisa kamu tangani sendiri, (f) bagaimana kamu akan bersikap pada diri sendiri saat 'terpeleset' & bereaksi kurang baik.",sample:"(a) Kotak alat: Teknik cepat, (1) napas kotak 4-4-4-4 sebanyak 6 kali, (2) grounding 5-4-3-2-1 sambil menekan kaki ke lantai. Kegiatan lebih panjang, (1) jalan kaki 15 menit dengan musik saat marah/butuh energi keluar, (2) menulis bebas 10 menit saat sedih/bingung. Orang tepercaya, kakakku (untuk didengar & pendapat), ibuku (untuk hal berat). (b) Mengenali emosi memuncak, di tubuh, rahang & bahu mengencang, napas jadi pendek, panas di wajah/dada (marah), atau perut mengganjal & napas dangkal (cemas). Di pikiran, muncul kata-kata ekstrem ('selalu', 'tidak pernah', 'semua orang', 'bencana') & dorongan kuat untuk membalas/lari/menyerah. (c) Aturan menunda reaksi, untuk apa pun yang berupa balasan pesan yang membuat marah, keputusan penting, atau konfrontasi, aku menunggu minimal beberapa jam (idealnya sampai besok) & menuliskan dulu apa yang ingin kusampaikan sebagai draf, baru memutuskan setelah lebih tenang. (d) Kebiasaan pendukung, tidur minimal 8 jam, bergerak/olahraga minimal 20 menit sehari, makan teratur (tidak melewatkan makan saat stres), & rutinitas menenangkan 10 menit sebelum tidur (peregangan + musik pelan). (e) Butuh dukungan lebih, aku akan bicara dengan ibu & wali kelas (& terbuka untuk konselor) bila, perasaan berat berlangsung hampir setiap hari lebih dari dua minggu tanpa membaik; mengganggu tidur, makan, atau sekolahku terus-menerus; membuatku kehilangan minat pada hampir semua hal yang biasa kunikmati; atau bila teknik-teknikku terasa tidak lagi cukup meski sudah kucoba konsisten. (f) Saat terpeleset, aku akan mengingatkan diri bahwa mengelola emosi adalah keterampilan yang dilatih seumur hidup & terpeleset itu bagian normal dari belajar; aku akan bertanggung jawab (minta maaf & memperbaiki bila menyakiti orang), merefleksikan apa yang bisa berbeda lain kali, lalu melanjutkan tanpa menghukum diri secara berlebihan, karena kritik diri yang keras justru membuatku lebih sulit pulih & mencoba lagi.",explain:"Jawaban baik: kotak alat yang lengkap & spesifik (teknik cepat + kegiatan + orang), tanda memuncak untuk tubuh & pikiran yang konkret, aturan menunda reaksi yang jelas & terikat waktu, kebiasaan fondasi yang relevan, kriteria butuh dukungan lebih yang konkret (durasi, dampak fungsi, hilangnya minat) dengan rencana bicara ke siapa, & sikap pada diri sendiri saat terpeleset yang seimbang antara bertanggung jawab & belas kasih (bukan self-blame berlebihan maupun mengabaikan dampak).",hint:"Bagian (e) & (f) yang paling penting untuk topik sensitif ini, buat kriteria butuh bantuan sangat konkret, & sikap pada diri saat terpeleset harus menggabungkan tanggung jawab DAN kebaikan pada diri."},
];
